// Generated by Repro from a screen recording. Fails while the bug exists.
import { test, expect } from '@playwright/test'

test('Checking off a task updates tasks left count', async ({ page }) => {
  await page.goto('/')
  await page.evaluate(() => localStorage.clear())
  await page.reload()

  await page.getByRole("textbox", { name: "New task", exact: true }).click()
  await page.waitForTimeout(700)
  await page.getByRole("textbox", { name: "New task", exact: true }).fill("Water plants")
  await page.getByRole("button", { name: "Save", exact: true }).click()
  await page.waitForTimeout(700)
  await page.getByRole("textbox", { name: "New task", exact: true }).click()
  await page.waitForTimeout(700)
  await page.getByRole("textbox", { name: "New task", exact: true }).fill("Reply to Sam")
  await page.getByRole("button", { name: "Save", exact: true }).click()
  await page.waitForTimeout(700)
  await page.getByRole("checkbox", { name: "Water plants", exact: true }).click()
  await page.waitForTimeout(700)
  await page.waitForTimeout(800)

  // Expected behaviour from the bug report
  await expect(page.getByText('1 task left', { exact: true })).toHaveCount(1);
  await expect(page.getByText('2 tasks left', { exact: true })).toHaveCount(0);
})
